# %% 01_DDRLBase.ipynb 17
def compute_discretization_grid(Rmin, # Minimum reward perceived
                                Rmax, # Maximum reward perceived
                                Nr # Number of gridpoints
                                ) -> tuple: # Gridpoints, Width 
    gridpoints = np.linspace(Rmin, Rmax, Nr)
    width  = np.round(gridpoints[1] - gridpoints[0], 8)
    return gridpoints, width

# %% 01_DDRLBase.ipynb 19
def dispatcher():
    dispatcher={'norm':stats.norm, 'alpha':stats.alpha, 'beta':stats.beta,
               'powerlaw':stats.powerlaw}
    return dispatcher

# %% 01_DDRLBase.ipynb 21
def compute_Risjasr(env, # The env object
                    Rmin,  # minimum perceived reward
                    Rmax,  # maximum perceived reward
                    nr,  # The number of reward bins
                    discretization_sigma # Width of the discritization normal distribution
                   ) -> np.ndarray: # Reward distribution
    # get the discretization grid
    points, width = compute_discretization_grid(Rmin, Rmax, nr)

    # init the reward distribution tensor
    Risjasr = np.zeros(env.R.shape + (nr,))  # last dim is distrib

    # go through the reward tensor of the environment
    for index, _ in np.ndenumerate(env.R):
        if env.disttype == 'continuous':  # return follows continuous distrib
            sigma = env.Rdict['scale'][index]  # sd
            loc = env.Rdict['loc'][index]  # mean
            dist = env.Rdict['dist'][index]  # distribution shape
            # choose the right distribution shape
            disp = dispatcher()
            func = disp[dist]
            # compute discretized distribution
            for r in range(nr):
                if r==0: # first interval
                    prop = func.cdf(points[r]+width/2, loc, sigma)
                elif r==nr-1: # last interval
                    prop = 1 - func.cdf(points[r]-width/2, loc, sigma)
                else: # all other intervals
                    prop = func.cdf(points[r]+width/2, loc, sigma)\
                        - func.cdf(points[r]-width/2, loc, sigma)   
                Risjasr[index +(r,)] = prop
                
        elif env.disttype == None:  # return is deterministic
            loc = env.R[index]  # mean
            sigma = discretization_sigma  # sigma
            func = stats.norm 
            # compute discretized distribution
            for r in range(nr):
                if r==0: # first interval
                    prop = func.cdf(points[r]+width/2, loc, sigma)
                elif r==nr-1: # last interval
                    prop = 1 - func.cdf(points[r]-width/2, loc, sigma)
                else: # all other intervals
                    prop = func.cdf(points[r]+width/2, loc, sigma)\
                        - func.cdf(points[r]-width/2, loc, sigma)   
                Risjasr[index +(r,)] = prop
        
        else:  # return follows discrete distribution
            x = env.Rdict['x'][index]  # values for which prob is non zero
            p = env.Rdict['p'][index]  # prob that return equals those values
            sigma = discretization_sigma  # discretization width
            func = stats.norm
            # compute discretized distribution
            for i in range(len(x)):
                for r in range(nr):
                    if r==0: # first interval
                        prop = p[i] * func.cdf(points[r]+width/2, x[i], sigma)
                    elif r==nr-1: # last interval
                        prop = p[i] * (1 - func.cdf(points[r]-width/2, x[i], sigma))
                    else: # all other intervals
                        prop = p[i] * (func.cdf(points[r]+width/2, x[i], sigma)\
                                       - func.cdf(points[r]-width/2, x[i], sigma))   
                    Risjasr[index +(r,)] += prop

    return Risjasr

# %% 01_DDRLBase.ipynb 32
# Smoothed Bellman Kronecker delta for Bellman equation
def compute_b_ivrv_(env, # env object
                    Rmin,
                    Rmax,
                    nr, # number of bins
                    discretization_sigma, # width of discretization normal distribution
                    gamma,  # discount factor
                    pre  # prefactor
                   ) -> np.ndarray: 
    
    points, width = compute_discretization_grid(Rmin, Rmax, nr)
    sigma = discretization_sigma
    b_ivrv_ = np.ones((env.N, nr, nr, nr)) * -1

    for v in range(nr):
        for r in range(nr):
            for v_ in range(nr):
                
                valv = pre * points[r] + gamma * points[v_]
                
                # gaussian distribution around valq with std `sig` 
                if v==0:
                    prop = stats.norm.cdf(points[v]+width/2, valv, sigma)
                elif v==nr-1: # last intervall
                    prop = 1 - stats.norm.cdf(points[v]-width/2, valv, sigma)
                else:
                    prop = stats.norm.cdf(points[v]+width/2, 
                                          valv, sigma) - stats.norm.cdf(points[v]-width/2, valv, sigma)
                    
                b_ivrv_[:,v,r,v_] = prop
    return b_ivrv_

# %% 01_DDRLBase.ipynb 34
class DDRLBase(abase):
    """
    Base class for deterministic strategy-average independent (multi-agent)
    temporal-difference reinforcement learning in strategy space.        
    """
    
    def __init__(self,
                 env, # An environment object
                 nr_reward_bins=8, # The number of bins to resolve rewards
                 discretization_sigma=0.1, # standard div for reward discretization
                 learning_rates=0.1, # agents' learning rates
                 discount_factors=0.0, # agents' discount factors
                 Rmin=None,  # minimum perceived reward
                 Rmax=None,  # maximum perceived reward
                 method='mean',  # biasing method
                 tau=0.5,  # tau for expectile and quantile methods
                 wU=1.,  # upper weight for weights method
                 choice_intensities=1.0, # agents' choice intensities
                 opteinsum=True,  # optimize einsum functions
                 use_prefactor=False,  # scale values with rewards
                 **kwargs):

        self.env = env
        Tt = env.T; assert np.allclose(Tt.sum(-1), 1)
        Rt = env.R 
        super().__init__(Tt, Rt, discount_factors, True, opteinsum)
        self.F = jnp.array(env.F)
        
        # learning rates
        self.alpha = make_variable_vector(learning_rates, self.N)

        # intensity of choice
        self.beta = make_variable_vector(choice_intensities, self.N)
        
        # discount factors
        self.gamma = make_variable_vector(discount_factors, self.N)
        
        # pre-factor
        self.pre = 1 - self.gamma if use_prefactor else jnp.ones(self.N)
        
        # number of reward bins
        self.nr = nr_reward_bins
        
        # reward discretization deviation 
        self.discsig = discretization_sigma
        
        # Rmin and Rmax
        if Rmin==None:
            self.Rmin = env.R.min()
        else:
            self.Rmin = Rmin
            
        if Rmax==None:
            self.Rmax = env.R.max()
        else:
            self.Rmax = Rmax
        
        # discretization grid
        disc_grid = compute_discretization_grid(self.Rmin, self.Rmax, self.nr)
        self.gridpoints = disc_grid[0]
        self.gridwidth = disc_grid[1]
        
        # reward tensor distribution
        self.Rr = compute_Risjasr(env, self.Rmin, self.Rmax, self.nr, self.discsig)
        
        # Bellman ivrv_
        self.b_ivrv_ = compute_b_ivrv_(env, self.Rmin, self.Rmax, self.nr, self.discsig, self.gamma, self.pre)
        
        # method
        self.method = method
        
        # value for quantile or expectile
        self.tau = tau
        
        # weights
        self.wU = wU

