@partial(jit, static_argnums=0)
def Visv(self:DDRLBase,
        Xisa  # Behavior profiles
        ) -> jnp.ndarray:
    M_iww_ = self.M_iww_(Xisa)
    Visv = jnp.ones((self.N, self.Z, self.nr)) * -1

    for i in range(self.N):
        mat = M_iww_[i].reshape(self.Z*self.nr, self.Z*self.nr)
        _pS = compute_stationarydistribution(mat)
        ix = jnp.max(jnp.where(_pS.mean(0)!=-10, jnp.arange(_pS.shape[0]), -1))
        pS = _pS[:, ix]
        
        Ps = pS.reshape(self.Z, self.nr).sum(-1)
        # assert jnp.allclose(self.Ps(Xisa), Ps, atol=1e-4)

        VIsv = pS.reshape(self.Z, self.nr) / pS.reshape(self.Z, self.nr).sum(-1, keepdims=True)
        
        Visv = Visv.at[i, ...].set(VIsv)

        # Visv[i, ...] = VIsv

    return Visv

DDRLBase.Visv = Visv 

# %% 01_DDRLBase.ipynb 51
@partial(jit, static_argnums=0)
def Vis(self:DDRLBase,
       Xisa  # Behavior profiles
       ) -> jnp.ndarray:
    Visv = self.Visv(Xisa)
    gpoints = jnp.ones((self.nr)) * -1
    gpoints = gpoints.at[:].set(self.gridpoints)
    Vism = jnp.einsum('ijk,k->ij', Visv, gpoints)  # mean of the distrib
    if self.method=='mean':  # take mean
        Vis = Vism
    elif self.method=='quantile':  # use quantile
        Vis = quantile(self.tau, Visv, gpoints)
    elif self.method=='expectile':  # use expectile
        Vis = expectile(self.tau, Visv, gpoints)
    elif self.method=='weights':  # use weights
        w = jnp.ones((self.N, self.Z, len(self.gridpoints)))
        n = jnp.newaxis
        upper = self.gridpoints[n,n,:] >= Vism[:,:,n]
        upper = upper * (self.wU - 1)
        w = w + upper
        wVisv = weights(w, Visv, gpoints)
        Vis = jnp.einsum('ijk,k->ij', wVisv, gpoints)  # take the new distrib's mean
    return Vis

DDRLBase.Vis = Vis  # Monkey-patching - possibly problematic?

# %% 01_DDRLBase.ipynb 56
@partial(jit, static_argnums=0)
def step(self:DDRLBase,
         Xisa,  # Behavior profiles
        ) -> jnp.ndarray:
    """
    Performs a learning step along the reward-prediction/temporal-difference error
    in strategy space, given joint strategy `Xisa`.
    """
    TDe = self.TDerror(Xisa)
    n = jnp.newaxis
    XexpaTDe = Xisa * jnp.exp(self.alpha[:,n,n] * TDe)
    return XexpaTDe / XexpaTDe.sum(-1, keepdims=True), TDe

DDRLBase.step = step

# %% 01_DDRLBase.ipynb 57
@partial(jit, static_argnums=0)
def reverse_step(self:DDRLBase,
                 Xisa,  # Behavior profiles
                 ) -> jnp.ndarray:
    """
    Performs a reverse learning step along the reward-prediction/temporal-difference error
    in strategy space, given joint strategy `Xisa`.
    """
    TDe = self.TDerror(Xisa)
    n = jnp.newaxis
    XexpaTDe = Xisa * jnp.exp(self.alpha[:,n,n] * -TDe)
    return XexpaTDe / XexpaTDe.sum(-1, keepdims=True), TDe

DDRLBase.reverse_step = reverse_step
